def check_case(case):
    from fractions import Fraction
    n = case['n_bits']
    expect = case['expect_claim']
    if not isinstance(n, int) or n < 0 or n > 12:
        return False
    N = 1 << n

    def gray(x):
        return x ^ (x >> 1)

    def inv_gray(g):
        x = g
        s = 1
        while s < n:
            x ^= x >> s
            s <<= 1
        return x

    def rev(x):
        r = 0
        for i in range(n):
            if (x >> i) & 1:
                r |= 1 << (n - 1 - i)
        return r

    gray_bij = len({gray(x) for x in range(N)}) == N
    rev_bij = len({rev(x) for x in range(N)}) == N
    inverse_ok = all(inv_gray(gray(x)) == x for x in range(N))
    defect = 0
    for x in range(N):
        if gray(rev(x)) != rev(gray(x)):
            defect += 1
    f = Fraction(defect, N)
    den_pow2 = (f.denominator & (f.denominator - 1)) == 0 and (N % f.denominator) == 0
    claim = bool(gray_bij and rev_bij and inverse_ok and den_pow2 and defect > 0)
    return bool(claim == expect)

