def _sona_orbit_count(m, n):
    seen = set()
    loops = 0
    for i in range(m):
        for j in range(n):
            if (i, j) not in seen:
                loops += 1
                a, b = i, j
                while (a, b) not in seen:
                    seen.add((a, b))
                    a = (a + 1) % m
                    b = (b + 1) % n
    return loops

def _lucas_odd_weight(N):
    total = 0
    c = 1
    for k in range(N + 1):
        if k > 0:
            c = c * (N - k + 1) // k
        if c & 1:
            total += 1
    return total

def _popcount(x):
    p = 0
    while x > 0:
        p += x & 1
        x >>= 1
    return p

def check_case(case):
    m = case['m']
    n = case['n']
    N = case['N']
    claim = False
    if m > 0 and n > 0 and N >= 0:
        sona_ok = (_sona_orbit_count(m, n) == gcd(m, n))
        lucas_ok = (_lucas_odd_weight(N) == (1 << _popcount(N)))
        claim = sona_ok and lucas_ok
    return bool(claim == case['expect_claim'])

