def check_case(case):
    from fractions import Fraction
    from math import gcd
    a1 = case['a1']; b1 = case['b1']; a2 = case['a2']; b2 = case['b2']
    n = case['n']; N1 = case['N1']; N2 = case['N2']
    D = a1 * b2 - a2 * b1
    if D == 0:
        return False
    if gcd(abs(a1), abs(b1)) != 1 or gcd(abs(a2), abs(b2)) != 1:
        return False
    if n < 1 or N1 < 1 or N2 < 1:
        return False
    m = 1 << n
    ok = True
    for x in range(m):
        y = x ^ (x >> 1)
        r = y
        s = 1
        while s < m:
            r ^= r >> s
            s = s << 1
        if r != x:
            ok = False
    if not ok:
        return False
    cert = Fraction(4 * D * D, N1 * N2)
    if Fraction(case['chord_num'], case['chord_den']) != cert:
        return False
    if cert < Fraction(4, N1 * N2):
        return False
    if Fraction(case['kap_num'], case['kap_den']) != Fraction(abs(a1) + abs(b1), abs(D)):
        return False
    return True
